def make(n):
    """Return a list of n single-element argument lists for Version(\"1.0.{i}\")."""
    return [[f"1.0.{i}"] for i in range(n)]

def make(n):
    """Return a list of n single-element argument lists for Version(\"1.{i}.0\")."""
    return [[f"1.{i}.0"] for i in range(n)]

def make(n):
    # Simple dot‑separated numeric versions – fast path in ``__init__``.
    return [[f"{i}.{i+1}.{i+2}"] for i in range(1, n + 1)]

def make(n):
    chunks = []
    for i in range(1, n+1):
        chunks.append(str(i).zfill(i))
    version = '.'.join(chunks) + 'c5'
    return [(version,)]
